"""Deterministic manuscript revision from the final round-five snapshot."""
import sys,json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent;P=HERE.parent;BACK=P/'archive/before_round6_20261015'
A=json.loads((HERE/'round6_analysis.json').read_text(encoding='utf-8'))
def paragraph(t,prefix,new):
    t,n=re.subn(r'(?m)^'+re.escape(prefix)+r'[^\n]*',lambda _:new,t);assert n==1,(prefix,n);return t
def main():
    t=(BACK/'TRA-20261014-V3.tex').read_text(encoding='utf-8')
    t=t.replace('Regulated Railway Product, Fare, and Frequency Design under Value-of-Time Polarization and Road Electrification','Regulated Railway Product, Fare, and Frequency Design under Income and Road-Cost Shocks')
    abstract="Railway pricing authority can improve operator profit while excluding price-sensitive travelers. We formulate a regulated product, fare and integer-frequency design problem with elastic participation and nested mode, product and seat choice. Three calibrated Chinese corridors reveal commercial profit gains accompanied by higher fares, service consolidation and lower railway-centered welfare. Tightening the fare cap from 1.20 to 1.10 reduces welfare losses by 51 to 79 percent but leaves welfare below the reference. Strict vulnerable-participation protection instead attains 69 to 95 percent of certified welfare benchmarks in the two single-OD corridors, retaining 36 to 42 percent of commercial profit gains. A 60-point certified cap--floor grid shows that a fare freeze reproduces much of this benefit, although the instruments select different fares and departures. Joint regulation changes the profit--welfare tradeoff without establishing universal complementarity. Income composition and cheaper road travel are scenario dimensions; differentiated-pricing comparisons retain search-based evidence. Conventional additions can support profitable incumbent adjustments while lowering traveler surplus, and their network welfare value depends on schedule convenience and newly served periods."
    assert len(abstract.split())<=200
    t=re.sub(r'\\begin\{abstract\}.*?\\end\{abstract\}',lambda _:r'\begin{abstract}'+'\n'+abstract+'\n'+r'\end{abstract}',t,flags=re.S)
    t=t.replace('The demand-side divergence is distributional rather than aggregate.','Income composition is one source of demand uncertainty relevant to regulation.')
    t=t.replace('For the regulated railway operator, these two shifts create a practical dilemma that cannot be resolved by adjusting a single instrument.','For the regulated railway operator, income uncertainty and road competition motivate a comparison of pricing authority, service obligations and mobility protection.')
    t=t.replace('What is missing from the existing literature is a single framework capable of supporting this joint decision under polarized demand and an electrified road competitor.','A joint framework is needed to compare fare and service regulation while tracking participation under income and road-cost shocks.')
    t=t.replace('Calibrated counterfactual applications then support a disciplined comparison of the market regimes in which a mixed HSR-and-conventional portfolio is preferred.','Calibrated counterfactual applications compare commercial pricing and service authority with fare caps, participation floors and welfare-oriented design.')
    old='A tighter fare cap reduces the loss, whereas strict vulnerable-participation protection delivers positive welfare while retaining part of the profit gain. Income composition and conventional additions have effects conditional on pricing authority, schedule value and resources. Calibration, schedule and fleet tests establish the scope of these findings.'
    new='A cap of 1.10 reduces commercial welfare losses, while a fare freeze and strict vulnerable-participation protection deliver positive welfare through different operating responses. A certified cap--floor grid compares these instruments and their combinations. Income composition, including polarization, is a scenario dimension; differentiated-pricing results remain exploratory because their global optima are not certified. Conventional additions, calibration, schedule and fleet tests establish the scope of the regulatory findings.'
    assert old in t;t=t.replace(old,new)
    t=paragraph(t,'The search alternates fare and frequency blocks,',r'HN/WC common-pricing domains use exhaustive period enumeration and a fleet-coupled integer master, imposing daily finance and vulnerable-participation constraints when the relaxed upper bound is unattainable. A certificate requires an optimal master solution satisfying all original constraints and matching its upper bound within 0.01 CNY/day; proven infeasibility and unresolved limits are recorded separately. JX and differentiated pricing use coordinated multi-start fare--frequency search, independent joint-neighborhood audits and repeated cross-scenario reference checks, without global optimality claims. Independent scalar calculations verify demand, feasibility and accounting for every reported design.'+'\n\n'+r'Computations run on 64-bit Windows 11 Pro with an AMD Ryzen 7 4800H processor (8 physical cores, 16 logical processors) and 16 GB installed memory (15.37 GiB available physical memory). The implementation uses Python 3.13.2, NumPy 2.5.0 and SciPy 1.18.0. COPT 8.0.6, accessed through coptpy 8.0.6, solves the enumerated HN/WC integer masters; SciPy\textquotesingle{}s HiGHS 1.12.0 solves their continuous LP relaxations for screening. The main batch uses eight worker processes and the focused cap--floor batch four, with one COPT and one BLAS/OpenMP thread per worker; JX and seat-specific pricing use the custom search rather than a COPT global solve.')
    t=t.replace('These are calibrated capacity savings, not observed efficiency estimates.','The lower JX headroom gain is consistent with its cap-driven commercial response: 86.8 percent of G/D departures are priced at the ceiling, separating fare authority from consolidation as a source of profit. These are calibrated capacity savings, not observed efficiency estimates.')
    t=t.replace(r'\subsection{Equal-mean polarization}',r'\subsection{Income composition and road-cost scenarios}')
    t=t.replace('The single-OD master proves P4 infeasibility in 3 states. The archive distinguishes these certificates from unresolved searches,','P3 is certified infeasible in all six states without a feasible design. For P4, three WC states are certified infeasible, while three HN states at polarization scale 1.50 and road intensities 0/0.25/0.50 reach the master time limit without a feasible witness; their feasibility remains open. The archive distinguishes certificates from unresolved searches,')
    t=t.replace('These comparisons concern the tested solutions rather than a universal effect of dispersion.','These comparisons are exploratory: differentiated-pricing search sensitivity prevents interpreting the increment as a certified polarization effect.')
    t=t.replace('The large central network increment is conditional on schedule inconvenience and transferred availability constants.','The two served-period variants use their own recalibrated P3 comparisons, rather than subtracting the central JX P3 welfare level. Reseeding both P3 and P4 with the current reference designs leaves their frequencies and fares unchanged, so their 11.5/2.5 thousand-CNY increments are invariant. The large central network increment is conditional on schedule inconvenience and transferred availability constants.')
    t=t.replace('HN/WC strict-floor profit designs are certified with hard finance and retention.','HN/WC strict-floor profit designs are certified with hard finance and retention. HN restores only eight of the eighteen commercially consolidated departures and retains 137 departures against 138 under a fare freeze; its selected near-reference fare pattern leaves 9.1 percent of the traveler-surplus loss, explaining why its recovery is lower than WC/JX despite satisfying the participation target.')
    anchor='The secondary operator budget ratio is'
    pos=t.index(anchor)
    addition=r'To compare direct fare restraint with participation protection, the HN/WC reference P3 experiment crosses caps 1.00/1.05/1.10/1.15/1.20 with floors 0.95/0.96/0.97/0.98/0.99/1.00 on the same 0.025 fare menu, fixed observed K and 50-percent G/D frequency authority. All 60 commercial optima are certified. Figure~\ref{fig:cap_floor_frontier} reports their sampled profit--welfare envelope and the certified welfare benchmarks; connecting lines do not establish the full attainable frontier.'+'\n\n'
    addition+=r'A fare freeze (cap 1.00, floor 0.95) yields profit/welfare gains of 535.4/480.9 thousand CNY/day in HN and 692.8/683.5 in WC. Strict participation alone (cap 1.20, floor 1.00) yields 569.9/388.9 and 757.0/730.4, respectively. Thus near-unit mean fares do not make the floor equivalent to a fare freeze: HN retains more profit and less welfare, whereas WC improves both relative to the frozen-fare commercial design. Cap 1.05 alone yields welfare gains of 197.1/167.5, well below the strict-floor outcomes.'+'\n\n'
    addition+=r'Combining cap 1.05 with floor 1.00 yields welfare gains of 521.0/734.0 thousand CNY/day, raising welfare by 132.1/3.6 above the floor alone while reducing profit by 4.2/0.8. These combinations lie on the sampled nondominated envelope and dominate the cap-1.00-only outcome, but trade profit for welfare relative to the same strict floor without the tighter cap. HN therefore benefits more from additional fare restraint than WC in this comparison; the experiment supports corridor-specific regulatory tradeoffs rather than universal complementarity.'+'\n\n'
    t=t[:pos]+addition+t[pos:]
    t=t.replace('Across distinct HN/WC state--policy--objective problems, 2,583 optima and 206 infeasible problems have finite-menu certificates; 63 remain without a certificate. JX and differentiated pricing retain the search scope stated above.','The inherited broad-domain ledger contains 2,583 certified HN/WC optima, 206 certified infeasible problems and 63 unresolved common-pricing problems; the separate 60-point cap--floor grid is fully certified. Some reported sensitivity outcomes draw on the unresolved set: K entry and stress screens, withdrawal and floor/budget variants, and the design-library and sensitivity summaries that include them use feasible witnesses where available. Central HN/WC P1--P4 results, the elasticity--cap profiles and the strict P3 floor comparisons are certified and do not rely on these open problems. Missing witnesses are recorded as open, never as infeasibility; the code archive maps every affected job, policy and objective to its status. JX and differentiated pricing retain the search scope stated above.')
    marker=r'\input{tables/v3_findings.tex}'
    figure=r'\begin{figure}[htbp]\centering\includegraphics[width=\textwidth]{fig/round6_frontier.pdf}\caption{Certified commercial outcomes across the HN/WC cap--floor grid. Blue circles identify cap-only outcomes at floor 0.95; orange diamonds identify additional floor-only outcomes at cap 1.20; green crosses identify additional joint outcomes. Coincident outcomes are shown once, and labels give selected cap or floor levels. Dashed lines connect the sampled nondominated outcomes, not a full feasible frontier; stars mark certified welfare optima at the reference cap and floor. Insets distinguish the strict-floor designs under caps 1.05 and 1.20. Every change is relative to the same-state P0.}\label{fig:cap_floor_frontier}\end{figure}'+'\n\n'
    t=t.replace(marker,figure+marker)
    t=t.replace('A tighter cap substantially reduces the loss while retaining much of the profit gain, but leaves welfare below P0.','Cap 1.10 substantially reduces the loss while retaining much of the profit gain, but leaves welfare below P0; a fare freeze yields positive welfare in the certified HN/WC comparisons.')
    t=t.replace('Equal-mean income changes alter the remaining value of differentiated pricing within fare and resource constraints.','Income composition is a scenario dimension of the regulatory problem. Equal-mean income comparisons suggest changes in the searched value of differentiated pricing within fare and resource constraints, but do not establish a globally certified effect of polarization.')
    t=t.replace('JX performs less well and remains conditional on network constraints and search quality.','The certified cap--floor grid shows that direct fare restraint can reproduce much of the strict-floor benefit; combinations offer corridor-specific tradeoffs without universally dominating either instrument. JX performs less well and remains conditional on network constraints and search quality.')
    t=paragraph(t,'The computational archive contains inputs,',r'The computational archive contains inputs, scenario definitions, physical decisions, independent scalar checks, joint-neighborhood audits, certificate ledgers and complete grids, including the 60 cap--floor optima and the Table~\ref{tab:k_reopening_events}B reseeding checks. Its environment record and README give hardware, package versions, worker settings and reproduction commands. COPT uses zero relative MIP gap, absolute gap $10^{-9}$ on thousand-CNY-scaled objectives and feasibility/dual tolerances $10^{-9}$; ordinary master limits are 120/180 seconds, with up to 600 seconds for priority recertification, and the HiGHS LP limit is 30 seconds. Exact dominance filtering, valid LP reduced-cost screening, integer fleet bounds and equivalent least-cost pooled-K representations accelerate enumeration; compatible cached certificates retain their originating solver provenance, including earlier SciPy/HiGHS MILP solves. A time limit is not an optimality or infeasibility certificate. The open-problem CSV maps affected publication inputs to their feasible-witness or unresolved status.')
    head,case=t.split(r'\section{Case study}',1);case=re.sub(r'(?<=\d)/(?=[-+]?\d)',lambda _:r'/\allowbreak{}',case);t=head+r'\section{Case study}'+case
    t=t.replace('15.37 GiB available physical memory','15.37 GiB reported physical memory')
    t=t.replace('The inherited broad-domain ledger contains','The broad-domain ledger contains')
    t=t.replace('63 unresolved common-pricing problems','63 unresolved common-pricing P4 problems (47 profit and 16 welfare objectives)')
    (P/'TRA-20261014-V3.tex').write_text(t,encoding='utf-8')
    # Keep table numbering and all validated numerical rows; clarify their scope.
    e=(BACK/'tables/v3_events.tex').read_text(encoding='utf-8')
    e=e.replace('Observed K remains fixed.','Observed K remains fixed. Half-slope/served and 60-min/served P3--P4 designs remain unchanged after reseeding from the current JX reference; each increment uses the matched recalibrated P3, not the central reference welfare value.')
    (P/'tables/v3_events.tex').write_text(e,encoding='utf-8')
    f=(BACK/'tables/v3_findings.tex').read_text(encoding='utf-8')
    f=f.replace('Protect participation alongside the fare cap','Compare participation floors with direct fare restraint')
    f=f.replace('Cap 1.10 alone leaves welfare below P0.','Cap 1.10 alone leaves welfare below P0; cap 1.00 restores positive welfare. Joint caps and floors give corridor-specific profit--welfare tradeoffs.')
    (P/'tables/v3_findings.tex').write_text(f,encoding='utf-8')
    print('round6 manuscript written; abstract words',len(abstract.split()))
if __name__=='__main__':main()
